"""Generated by OpenAI Codex on 2026-11-03. Six-result location search and walking routes."""

from typing import Annotated

from api.dependencies import db_session
from api.routers.campus_map.map import Identity
from fastapi import APIRouter, HTTPException, Query
from services.campus_map import load_graph
from services.navigation import name_rank, normalized, route
from sqlalchemy import text

router = APIRouter(prefix="/api/map", tags=["Navigation"])


@router.get("/search")
def search(
    db: db_session,
    identity: Identity,
    q: Annotated[str, Query(min_length=1, max_length=120)],
):
    term = normalized(q)
    if not term:
        return {"results": []}
    escaped = term.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
    rows = db.execute(
        text("""SELECT f.id,COALESCE(f.tags->>'name',n.name) AS name,n.name AS matched_name,n.kind,
        COALESCE(f.tags->>'amenity',CASE WHEN f.tags ? 'building' THEN 'building' END,f.tags->>'highway',f.object_type) AS category
        FROM map_names n JOIN map_features f ON f.id=n.feature_id
        WHERE f.geom IS NOT NULL AND (n.name ILIKE :contains OR n.name % :term)
        ORDER BY CASE WHEN lower(n.name)=:term THEN 0 WHEN n.name ILIKE :prefix THEN 1 WHEN n.name ILIKE :contains THEN 2 ELSE 3 END,
        similarity(n.name,:term) DESC,length(n.name),f.id LIMIT 240"""),
        {"term": term, "contains": "%" + escaped + "%", "prefix": escaped + "%"},
    ).mappings()
    best = {}
    for row in rows:
        rank = (
            *name_rank(term, row["matched_name"]),
            0 if row["kind"] == "name" else 1,
            row["id"],
        )
        if row["id"] not in best or rank < best[row["id"]][0]:
            best[row["id"]] = (rank, dict(row))
    return {
        "results": [
            entry[1] for entry in sorted(best.values(), key=lambda entry: entry[0])[:6]
        ]
    }


@router.get("/route")
def directions(
    db: db_session,
    identity: Identity,
    start: Annotated[str, Query(max_length=100)],
    destination: Annotated[str, Query(max_length=100)],
):
    revision = db.execute(
        text("SELECT revision FROM map_dataset WHERE singleton FOR SHARE")
    ).scalar_one()
    objects = load_graph(db)
    try:
        result = route(objects, start, destination)
    except KeyError as exc:
        raise HTTPException(404, str(exc)) from exc
    except ValueError as exc:
        raise HTTPException(422, str(exc)) from exc
    result["properties"]["revision"] = revision
    return result
